entries[55090] = { ["name"] = "Geißelstoß", ["text"] = "1 Unheilige Rune / -10 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nEin unheiliger Stoß, der 135% Waffenschaden als körperlichen Schaden plus 597 verursacht. Für jede Eurer auf das Ziel wirkenden Krankheiten fügt Ihr zusätzlich 25% des verursachten körperlichen Schadens als Schattenschaden zu." }
