entries[55099] = { ["name"] = "Schlangenumschlingung", ["text"] = "40 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nWürgt den Gegner und macht ihn 3 Sek. lang bewegungsunfähig. Nach Ende der Wirkungszeit wird das Ziel von Schlangen umschlungen, die es 10 Sek. lang betäuben. Das Ziel kommt frei, falls die Schlangen getötet werden." }
