entries[55974] = { ["name"] = "Siedendes Blut", ["text"] = "Sofort 15 sek. Abklingzeit\nVerursacht, dass alle Krankheitseffekte auf Zielen innerhalb von 30 Metern schmerzvoll ausbrechen und dabei 2250 bis 2750 Schaden verursachen (modifiziert durch Angriffskraft). Zwingt alle Ziele dazu, bis Abbruch lang den Todesritter anzugreifen." }
