entries[55976] = { ["name"] = "Zauberabwehr", ["text"] = "Wirken in 1 sek.\nGreift in der Nähe befindliche Feinde mit einem Wirbel von Stahl an, der 6 Sek. lang anhält und alle 2 Sek. Waffenschaden verursacht. Verleiht dem Zaubernden zeitweilige Magie-Immunität." }
entries[55977] = { ["name"] = "Wirbelwind", ["text"] = "Sofort\nReflektiert Magie.\nFügt allen Gegnern in der Nähe alle 2 Sek. normalen Schaden zu." }
entries[55978] = { ["name"] = "Herzstoß", ["text"] = "-10 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nEin brutaler Angriff, der den Feind sofort schlägt und 150% Waffenschaden plus für jede auf das Ziel wirkende Krankheit zusätzlich 615 Schaden verursacht. Ziele dieses Angriffs können 10 Sek. lang keine Hasteffekte nutzen." }
entries[55980] = { ["name"] = "Mammuttrampeln", ["text"] = "Wirken in 0.25 sek. 4 sek. Abklingzeit\nVerursacht bei Feinden innerhalb von 10 Metern 5266 bis 7734 Schaden." }
entries[55981] = { ["name"] = "Mammuttrompeten", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
entries[55982] = { ["name"] = "Mammutsturmangriff", ["text"] = "5 - 30 Meter Reichweite\nWirken in 0.9 sek. 8 sek. Abklingzeit\nStürmt auf einen Gegner zu, verursacht normalen Schaden plus 2647 bis 2953 und betäubt ihn 3 Sek. lang." }
entries[55983] = { ["name"] = "Zur Ruhe betten", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nLasst Hodirs Horn erklingen, wenn Ihr bei den Überresten eines Vorfahren von Niffelem oder eines ruhelosen Frosterben steht." }
entries[55984] = { ["name"] = "Schattenblitz", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 2.5 sek.\nSchleudert einen Blitz aus dunkler Magie auf einen Gegner, verursacht Schattenschaden und erhöht 10 Sek. lang erlittenen Schattenschaden um 10%." }
